-- Modify "dashboards" table
ALTER TABLE "dashboards" ADD COLUMN "site" character varying NOT NULL DEFAULT '', ADD COLUMN "description" character varying NOT NULL DEFAULT '', ADD COLUMN "default_range" character varying NOT NULL DEFAULT '', ADD COLUMN "custom_css" text NOT NULL DEFAULT '';
-- Modify "endpoints" table
ALTER TABLE "endpoints" ADD COLUMN "site" character varying NOT NULL DEFAULT '';
-- Create "sites" table
CREATE TABLE "sites" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "key" character varying NOT NULL, "position" bigint NOT NULL, "hosts" jsonb NULL, "dashboards" jsonb NULL, "all_dashboards" boolean NOT NULL DEFAULT false, "private" boolean NOT NULL DEFAULT false, "allowed_groups" jsonb NULL, "ui" bytea NOT NULL, "source" character varying NOT NULL DEFAULT 'config', PRIMARY KEY ("id"));
-- Create index "sites_key_key" to table: "sites"
CREATE UNIQUE INDEX "sites_key_key" ON "sites" ("key");
